import 'package:jitan_models/jitan_models.dart';

import 'api_client_exception.dart';
import 'api_transport.dart';

/// `/recovery/*`: the Employee app's Sign in → Recover account flow. No
/// sign-in; the scanned temporary recovery QR (generated by HR/Admin after
/// Reset account access) is the credential.
class RecoveryApi {
  const RecoveryApi(this._transport);

  final ApiTransport _transport;

  /// The account a scanned recovery QR is for. Fails with e.g.
  /// `account_not_reset`, `qr_expired`, `qr_already_used`, `qr_wrong_purpose`.
  Future<EmployeeAccount> start(String qrCode) async {
    final json = await _transport.postJson('recovery/start', RecoveryStartRequest(qrCode: qrCode).toJson());
    return _decode('Recovery account', () => EmployeeAccount.fromJson(json));
  }

  /// Sets the new password and returns the session for this device.
  Future<SessionResponse> complete(RecoveryCompleteRequest request) async {
    final json = await _transport.postJson('recovery/complete', request.toJson());
    return _decode('Recovery result', () => SessionResponse.fromJson(json));
  }

  static T _decode<T>(String what, T Function() decode) {
    try {
      return decode();
    } on FormatException catch (e) {
      throw ApiClientException.invalidResponse(200, '$what: ${e.message}');
    }
  }
}
